#!/usr/bin/env python3

import sys
from html.parser import HTMLParser
from io import StringIO


class JavaScriptRemover(HTMLParser):
    def __init__(self):
        super().__init__()
        self.output = StringIO()
        self.skip_content = False
        self.dangerous_tags = {'script', 'style'}
        self.dangerous_attributes = {
            'onclick', 'onload', 'onunload', 'onchange', 'onsubmit',
            'onmouseover', 'onmouseout', 'onmousemove', 'onkeydown',
            'onkeyup', 'onkeypress', 'ondblclick', 'onfocus', 'onblur',
            'onerror', 'onabort', 'onscroll', 'oninput', 'onwheel',
            'oncontextmenu', 'ondrag', 'ondrop', 'onpaste', 'oncopy'
        }

    def handle_starttag(self, tag, attrs):
        if tag.lower() in self.dangerous_tags:
            self.skip_content = True
            return

        clean_attrs = []
        for attr, value in attrs:
            if attr.lower() in self.dangerous_attributes:
                continue
            if attr.lower() in {'href', 'src', 'data'} and value:
                if isinstance(value, str) and value.lower().startswith('javascript:'):
                    continue
            clean_attrs.append((attr, value))

        self.output.write(f'<{tag}')
        for attr, value in clean_attrs:
            if value is None:
                self.output.write(f' {attr}')
            else:
                self.output.write(f' {attr}="{value}"')
        self.output.write('>')

    def handle_endtag(self, tag):
        if tag.lower() in self.dangerous_tags:
            self.skip_content = False
            return
        self.output.write(f'</{tag}>')

    def handle_data(self, data):
        if not self.skip_content:
            self.output.write(data)

    def handle_comment(self, data):
        self.output.write(f'<!--{data}-->')

    def handle_decl(self, decl):
        self.output.write(f'<!{decl}>')

    def handle_entityref(self, name):
        self.output.write(f'&{name};')

    def handle_charref(self, name):
        self.output.write(f'&#{name};')

    def get_output(self):
        return self.output.getvalue()


def remove_javascript(html_content):
    remover = JavaScriptRemover()
    remover.feed(html_content)
    return remover.get_output()


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: filter.py <html_file>", file=sys.stderr)
        sys.exit(1)

    filepath = sys.argv[1]

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()

        cleaned = remove_javascript(content)

        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(cleaned)

        print(f"Successfully removed JavaScript from {filepath}")
    except FileNotFoundError:
        print(f"Error: File not found: {filepath}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

